Translate("deDE", "gnomeregan", {
	title = "Gnomeregan",
	aliases = { "Stadt Gnomeregan" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Gnomeregan war die Stadt der {link:gnomes}Gnome{/link}, ein Wunder der Welt, erbaut in die westlichen Hügel von {link:dun-morogh}Dun Morogh{/link}. Ihre Hallen waren voller großer Maschinen, Uhrwerkdiener und Apparate, die sich kein anderes Volk hätte erträumen können. Heute ist sie eine vergiftete Ruine. Ihre Tore werden von den kranken und wahnsinnigen Überlebenden ihres Falls bewacht, in ihren Tiefen wimmelt es von {link:troggs}Troggs{/link} und lebendem Schleim, und in ihrem Herzen sitzt der Gnom, der sie verraten hat.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Die {link:gnomes}Gnome{/link} erbauten Gnomeregan mit eigenen Händen, als Nachbarn und Freunde der {link:dwarves}Zwerge{/link} von {link:ironforge}Ironforge{/link}. Keine Chronik verzeichnet das Jahr ihrer Gründung. Über Generationen war sie der Sitz des Hochtüftlers und der Stolz des gnomischen Volkes, und aus ihren Werkstätten kamen viele der Maschinen, die der {link:alliance}Allianz{/link} im {link:second-war}Zweiten Krieg{/link} dienten.]=],
		},
		{
			title = "Der Fall",
			text = [=[Die {link:troggs}Troggs{/link} stiegen aus den Tiefen unter der Stadt empor, in einer Zahl, der die {link:gnomes}Gnome{/link} nicht standhalten konnten. Der Hochtüftler {link:gelbin-mekkatorque}Gelbin Mekkatorque{/link} beschloss, sie mit einer Waffe aus gnomischer Fertigung auszumerzen. Sie tötete Troggs, doch sie tötete auch sehr viele Gnome, und sie ließ die Stadt von Gift durchtränkt zurück. Viele, die überlebten, wurden zu Leprösen, krank am Leib und leer im Geist. Die übrigen flohen nach {link:ironforge}Ironforge{/link}. Hinter ihnen nahm {link:mekgineer-thermaplugg}Robogenieur Thermaplugg{/link}, dem der Hochtüftler vertraut hatte, die Stadt für sich.]=],
		},
		{
			title = "Innerhalb der Mauern",
			text = [=[• {b}Der Eingang.{/b} Eine Gnomin namens Emi Shortfuse hält die Tore mit Sprengstoff und sehr wenig Geduld gegen die {link:troggs}Troggs{/link}.
• {b}Die Saubere Zone.{/b} Eine Schar gnomischer Ausharrender klammert sich an einen giftfreien Raum, in dem eine seltsame Maschine namens Sparklematic 5200 noch immer alles schrubbt und verpackt, was man ihr gibt.
• {b}Die Tiefen.{/b} Vergiftete Schleime, kaputte Maschinen und ein abtrünniger Roboter namens Techbot streifen durch die unteren Hallen. Einst war er ein Helfer der Tüftler. Ein Funke kehrte seinen Verstand um.
• {b}Die Herren.{/b} {link:grubbis}Grubbis{/link} führt die Troggs in der Stadt an. {link:mekgineer-thermaplugg}Thermaplugg{/link} befehligt die leprösen {link:gnomes}Gnome{/link} und die Maschinen. {link:dark-iron-dwarves}Dunkeleisenzwerge{/link} bewegen sich frei unter ihnen, und bisweilen findet man einen Gesandten der Dunkeleisen in den Hallen.]=],
		},
		{
			title = "Bosse",
			text = [=[• {b}{link:grubbis}Grubbis{/link}{/b}, Häuptling der {link:troggs}Troggs{/link} von Gnomeregan.
• {b}{link:viscous-fallout}Viscous Fallout{/link}{/b}, eine lebende Masse aus dem Gift der Stadt.
• {b}{link:electrocutioner-6000}Electrocutioner 6000{/link}{/b}, eine Kriegsmaschine, die noch immer ihren Posten bewacht.
• {b}{link:crowd-pummeler-9-60}Crowd Pummeler 9-60{/link}{/b}, ein massiger mechanischer Schläger.
• {b}{link:dark-iron-ambassador}Dunkeleisenbotschafter{/link}{/b}, ein Gesandter der {link:dark-iron-dwarves}Dunkeleisen{/link}, der nicht immer zugegen ist.
• {b}{link:mekgineer-thermaplugg}Robogenieur Thermaplugg{/link}{/b}, der Verräter, der über die Ruinen herrscht.]=],
		},
		{
			title = "In der Gegenwart",
			text = [=[Die Verbannten von Gnomeregan haben ihre Stadt nicht vergessen. Von {link:tinker-town}Tinker Town{/link} aus schicken sie Freiwillige zurück durch ihre Tore, um verlorene Aufzeichnungen zu retten, Teile zu bergen und die Maschinen zu sichern, die sie zurückließen. In {link:kharanos}Kharanos{/link} sammeln zwei {link:gnomes}Gnome{/link} das Gift der Stadt in der Hoffnung auf ein Heilmittel. Und die Goblins der {link:horde}Horde{/link} haben erfahren, dass {link:mekgineer-thermaplugg}Thermaplugg{/link} eine große Maschine baut, einen Apparat, besser als jeder ihrer eigenen, und sie wollen seine Pläne.]=],
		},
	},
})

Translate("deDE", "mekgineer-thermaplugg", {
	title = "Robogenieur Thermaplugg",
	subtitle = "Der Verräter von Gnomeregan",
	found = "Die tiefste Halle von Gnomeregan",
	allegiance = "Er selbst",
	aliases = { "Thermaplugg", "Sicco Thermaplugg" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Robogenieur Sicco Thermaplugg war einst einer der vertrautesten {link:gnomes}Gnome{/link} Gnomeregans. Der {link:gelbin-mekkatorque}Hochtüftler Gelbin Mekkatorque{/link} verließ sich auf ihn. Als die Stadt fiel, floh Thermaplugg nicht mit seinem Volk. Er blieb und machte sich zum Herrn der Ruinen. Die Gnome von {link:tinker-town}Tinker Town{/link} sprechen seinen Namen so aus, wie die {link:dwarves}Zwerge{/link} die Namen der {link:dark-iron-dwarves}Dunkeleisen{/link} aussprechen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Thermaplugg ist der Grund, warum der Fall Gnomeregans als Verrat in Erinnerung bleibt und nicht nur als Unglück. Sein Verrat machte aus einer Katastrophe eine Wunde, die die {link:gnomes}Gnome{/link} nicht heilen lassen können. Solange er die Stadt hält, kann sie nicht zurückerobert werden.]=],
		},
		{
			title = "Taten",
			text = [=[• Er verriet den Hochtüftler und das gnomische Volk beim Fall von {link:gnomeregan}Gnomeregan{/link}.
• Er herrscht über die vergiftete Stadt mit einem Heer aus leprösen Gnomen, {link:troggs}Troggs{/link} und Kriegsmaschinen.
• Er verhandelt mit den Dunkeleisenzwergen, die sich frei durch seine Hallen bewegen und seine Arbeit unterstützen.
• Er baut einen großen Apparat neuer Bauart, dessen Pläne in einem Tresor nahe seinem Thron liegen.]=],
		},
		{
			title = "Der König des Nichts",
			text = [=[Was Thermaplugg wollte, kann {link:gelbin-mekkatorque}Mekkatorque{/link} noch immer nicht sagen. Macht vielleicht, oder Reichtum. Beides wäre ihm mit der Zeit zugefallen, hätte er nur gewartet. Stattdessen wählte er einen Thron in einer Ruine, umgeben von den wahnsinnigen Resten des Volkes, dem er einst diente. Der Hochtüftler nennt ihn den König des Nichts. Doch der Verräter ist nicht untätig. Seine Maschinen summen noch immer in den Tiefen, und die Goblins der {link:horde}Horde{/link} flüstern, sein neuer Apparat übertreffe jeden Schredder, den sie je gebaut haben. Ein gefangener {link:gnomes}Gnom{/link}, der aus seinen Hallen entkam, schwor, die {link:dark-iron-dwarves}Dunkeleisen{/link} hätten bei seinem Bau die Hand im Spiel gehabt.]=],
		},
		{
			title = "Unverzeichnet",
			text = [=[Wenig ist über Thermapluggs Leben vor dem Fall geschrieben, oder darüber, wie er so hoch im Vertrauen des Hochtüftlers aufstieg.]=],
		},
	},
	chapters = {
		{
			title = "Der große Verrat",
			hint = "Tragt das Urteil des Hochtüftlers ins Herz von Gnomeregan.",
			text = [=[{link:gelbin-mekkatorque}Mekkatorque{/link} verlangte nur eines von denen, die für {link:gnomeregan}Gnomeregan{/link} kämpfen wollten: dass sie den Verräter töteten. Als die Tat vollbracht war, sagte der Hochtüftler, er hoffe, das Letzte, was Thermaplugg je gespürt habe, sei ein Stiefel gewesen. Dann sprach er von dem, was wirklich zählte. Mit dem Verräter fort waren die {link:gnomes}Gnome{/link} der Heimkehr einen Schritt näher.]=],
		},
		{
			title = "Der Apparat",
			hint = "Nehmt, was Thermaplugg neben seinem Thron verschlossen hat.",
			text = [=[Die Baupläne des Apparats lagen in einem Tresor nahe Thermaplugg, und nur er kannte die Kombination. Der Goblin-Ingenieur Nogg aus {link:orgrimmar}Orgrimmar{/link} wollte sie so sehr, dass er Fremde in die tiefste Halle von {link:gnomeregan}Gnomeregan{/link} schickte. Wohin gnomischer Erfindungsgeist geht, folgt goblinischer Profit.]=],
		},
	},
	mentions = {
		{ text = "Ein schönes Durcheinander" },
		{ text = "Apparatekriege" },
	},
	bonds = {
		{ id = "gelbin-mekkatorque", name = "Gelbin Mekkatorque", note = "der Hochtüftler, den er verriet" },
		{ id = "grubbis", name = "Grubbis", note = "führt die Troggs seiner Stadt an" },
		{ id = "dark-iron-ambassador", name = "Dunkeleisenbotschafter", note = "ein Gesandter seiner Verbündeten" },
	},
})

Translate("deDE", "grubbis", {
	title = "Grubbis",
	subtitle = "Häuptling der Troggs von Gnomeregan",
	found = "Die äußeren Hallen von Gnomeregan, nahe dem Eingang",
	allegiance = "Troggs von Gnomeregan",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Grubbis ist der Trogghäuptling, der seine Art in den Hallen von {link:gnomeregan}Gnomeregan{/link} anführt. Er kämpft nicht allein. Eine große Bestie namens Chomper folgt ihm in die Schlacht. Wenn die Gnomin Emi Shortfuse ihre Ladungen anbringt, um die Tunnel nahe den Stadttoren zu versiegeln, sind es Grubbis und seine Krieger, die aus der Dunkelheit strömen, um sie aufzuhalten.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Grubbis ist das Gesicht der Trogginvasion, die {link:gnomeregan}Gnomeregan{/link} brach. Die Säuberung der {link:gnomes}Gnome{/link} hat sein Volk nicht vernichtet; sie hat es nur seltsamer gemacht.]=],
		},
	},
	bonds = {
		{ id = "mekgineer-thermaplugg", name = "Robogenieur Thermaplugg", note = "teilt die Ruinen mit ihm" },
	},
})

Translate("deDE", "viscous-fallout", {
	title = "Viscous Fallout",
	subtitle = "Das lebende Gift",
	found = "Die vergifteten Tiefen von Gnomeregan",
	allegiance = "Keine",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Viscous Fallout ist das, was die Säuberung Gnomeregans zurückließ. Es ist eine wogende Masse grünen Schleims, geboren aus dem Gift, das die Stadt überflutete, und es lauert in den Tiefen, wo das Gift am dicksten fließt. Kleinere Schleime und Schrecken kriechen um es herum. Die {link:gnomes}Gnome{/link}, die das Gift in {link:kharanos}Kharanos{/link} erforschen, wollen Proben von solchen Kreaturen, frisch genommen, denn sie sagen, der Niederschlag der {link:troggs}Troggs{/link} sei für ihre Arbeit zu schwach.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Viscous Fallout ist die eigene Waffe der {link:gnomes}Gnome{/link}, die einen Körper erhalten hat. Es ist der eine Feind in {link:gnomeregan}Gnomeregan{/link}, für den niemand anderem die Schuld gegeben werden kann.]=],
		},
	},
})

Translate("deDE", "electrocutioner-6000", {
	title = "Electrocutioner 6000",
	subtitle = "Wächtermaschine von Gnomeregan",
	found = "Die Hallen von Gnomeregan",
	allegiance = "Maschinen von Gnomeregan",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Electrocutioner 6000 ist eine große Kriegsmaschine Gnomeregans, bewaffnet mit Blitzen. Sie wurde gebaut, um die Stadt zu bewachen. Ihre Erbauer sind fort, vergiftet oder im Exil, doch die Maschine steht noch immer auf ihrem Posten und streckt jeden nieder, der ihr zu nahe kommt.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Der Electrocutioner zeigt die bittere Seite gnomischen Genies. Die Verteidigungsanlagen der Stadt waren zu gut gebaut, und nun verteidigen sie sie gegen ihr eigenes Volk.]=],
		},
	},
})

Translate("deDE", "crowd-pummeler-9-60", {
	title = "Crowd Pummeler 9-60",
	subtitle = "Mechanischer Schläger",
	found = "Eine große Halle von Gnomeregan",
	allegiance = "Maschinen von Gnomeregan",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Crowd Pummeler 9-60 ist eine massige Maschine Gnomeregans, gebaut, wie ihr Name prahlt, um Menschenmengen niederzuschlagen. Noch immer stampft und schwingt sie in einer der großen Hallen der Stadt, als sähen ihre Erbauer zu. Ob die {link:gnomes}Gnome{/link} sie zum Vergnügen, für den Krieg oder zur Wahrung der Ordnung in ihren Straßen bauten, hat kein Überlebender zu sagen geruht.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Wie vieles, was die {link:gnomes}Gnome{/link} zurückließen, hat der Pummeler seinen Zweck überdauert und seine Kraft behalten.]=],
		},
	},
})

Translate("deDE", "dark-iron-ambassador", {
	title = "Dunkeleisenbotschafter",
	subtitle = "Gesandter der Dunkeleisen",
	found = "Die Hallen von Gnomeregan (nicht immer zugegen)",
	allegiance = "Dunkeleisenzwerge",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Dunkeleisenbotschafter ist ein Gesandter der {link:dark-iron-dwarves}Dunkeleisen{/link}, der bisweilen in den Hallen von {link:gnomeregan}Gnomeregan{/link} anzutreffen ist, von Feuer bewacht. Welche Geschäfte die Dunkeleisen mit {link:mekgineer-thermaplugg}Thermaplugg{/link} haben, steht nirgends geschrieben. Doch die Zeichen sind zahlreich: ein gefangener {link:gnomes}Gnom{/link}, von Dunkeleisenzwergen geschlagen, der Ring eines gnomischen Juweliers, gefunden an der Leiche eines Dunkeleisens, und ein neuer Apparat, gebaut mit Hilfe der Dunkeleisen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Der Botschafter ist der Beweis, dass der Untergang Gnomeregans Teil eines größeren Netzes ist und dass der alte Feind Ironforges auch in die Stadt der {link:gnomes}Gnome{/link} hineingegriffen hat.]=],
		},
	},
	bonds = {
		{ id = "mekgineer-thermaplugg", name = "Robogenieur Thermaplugg", note = "der Verräter, mit dem er verhandelt" },
	},
})
